    from pytest import structs

    # Get the original implementation
    import pytest._code
    import pytest._runner

    # Get the original from_item_and_call method
    if hasattr(cls, '_original'):
        result = cls._original(*args, **kwargs)
    else:
        # Try to call the original through the class hierarchy
        for base in cls.__mro__:
            if hasattr(base, 'from_item_and_call') and base.from_item_and_call != cls.from_item_and_call:
                result = base.from_item_and_call(*args, **kwargs)
                break
        else:
            # Fallback - create a minimal report
            result = structs.TestReport(
                name=kwargs.get('name', 'unknown'),
