sys.setrecursionlimit(2000000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    p = list(map(int, lines[2].split()))
    m = int(lines[3])
    b = list(map(int, lines[4].split()))

    INF = float('inf')

    # Early impossibility check: b must be strictly increasing
    for i in range(m - 1):
        if b[i] >= b[i+1]:
            return 'NO\n' + str('0')

    # Store all positions for each value in a
    pos_by_value = defaultdict(list)
    for i in range(n):
        pos_by_value[a[i]].append(i)

    # Check if all values in b exist in a
    for val in b:
        if val not in pos_by_value:
            return 'NO\n' + str('0')

    # Precompute: for each position i, prefix sum of costs
    # cost[i] = sum of p[0..i-1]
    prefix_cost = [0] * (n + 1)
    for i in range(n):
        prefix_cost[i + 1] = prefix_cost[i] + (p[i] if p[i] < 0 else 0)
        # Actually, we only care about positive p for deletion cost

    prefix_cost = [0] * (n + 1)
    for i in range(n):
        prefix_cost[i + 1] = prefix_cost[i] + (0 if p[i] < 0 else p[i])

    # For each position and each b, precompute cost to delete all elements >= b between positions
    # Precompute total cost to delete all elements >= v in a suffix
    # This is expensive, so let's do it on demand

    # dp[i] = dict mapping position -> min cost to have matched b[0..i] ending at that position
    dp = [{} for _ in range(m)]

    def get_suffix_ge_cost(pos, threshold):
        """Calculate sum of p[j] for j >= pos where a[j] >= threshold"""
        cost = 0
        for j in range(pos, n):
            if a[j] >= threshold:
                cost += p[j]
        return cost

    # Initialize for b[0]
    b0 = b[0]
    if b0 not in pos_by_value:
        return 'NO\n' + str('0')

    for pos in pos_by_value[b0]:
        # Cost to delete elements before pos that are >= virtual(-1)
        # Actually, we only delete elements that would become running max
        # Before b[0], everything can be deleted regardless

        cost = 0
        for j in range(pos):
            if a[j] >= 1:  # everything >= 1
                cost += p[j]

        dp[0][pos] = cost

    # if possible, return early since we might have found valid
    if 0 in dp[0]:
        min_initial = min(dp[0].values())

        # Try to complete the sequence
        for i in range(1, m):
            bi = b[i]
            prev_bi = b[i-1]

            cur_dp = {}
            if prev_bi not in pos_by_value or bi not in pos_by_value:
                min_final = INF
            else:
                for p1 in pos_by_value[prev_bi]:
                    for p2 in pos_by_value[bi]:
                        if p1 >= p2:
                            continue

                        # Transition cost: delete all a[j] for p1 < j < p2 with a[j] >= prev_bi
                        trans_cost = 0
                        for j in range(p1 + 1, p2):
                            if a[j] >= prev_bi:
                                trans_cost += p[j]

                        for pos in cur_dp if cur_dp else [p2]:
                            pass

                    if p1 in dp[i-1]:
                        base_cost = dp[i-1][p1]

                        # Among all positions for bi, find minimum
                        trans_cost = 0
                        for j in range(p1 + 1, p2):
                            if a[j] >= prev_bi:
                                trans_cost += p[j]

                        new_cost = base_cost + trans_cost
                        if p2 not in cur_dp or new_cost < cur_dp[p2]:
                            cur_dp[p2] = new_cost

                if cur_dp:
                    dp[i] = cur_dp
                else:
                    dp[i] = {}

        if dp[m-1]:
            min_final = min(dp[m-1].values())
            return f'YES\n{min_final}'

    dp = [{} for _ in range(m)]

    for pos in pos_by_value[b0]:
        cost = 0
        for j in range(pos):
            if a[j] >= 1:
                cost += p[j]
        dp[0][pos] = cost

    for i in range(1, m):
        cur_dp = {}
        prev_bi = b[i-1]
        bi = b[i]

        valid_pos_prev = pos_by_value.get(prev_bi, [])
        valid_pos_curr = pos_by_value.get(bi, [])

        if not valid_pos_prev or not valid_pos_curr:
            dp[i] = cur_dp
            continue

        for p1 in valid_pos_prev:
            if p1 not in dp[i-1]:
                continue

            for p2 in valid_pos_curr:
                if p1 >= p2:
                    continue

                trans_cost = 0
                for j in range(p1 + 1, p2):
                    if a[j] >= prev_bi:
                        trans_cost += p[j]

                new_cost = dp[i-1][p1] + trans_cost
                if p2 not in cur_dp or new_cost < cur_dp[p2]:
                    cur_dp[p2] = new_cost

        dp[i] = cur_dp

    result_min = INF
    for cost in dp[m-1].values():
        result_min = min(result_min, cost)

    if result_min == float('inf'):
        return 'NO\n' + str('0')

    return f'YES\n{result_min}'

