import itertools

def calculate_max_consecutive_n(seq):
    """Calculate the maximum number of consecutive 'N' characters in a sequence."""
    max_n = 0
    count = 0
    for c in seq:
        if c == 'N':
            count += 1
            max_n = max(max_n, count)
        else:
            count = 0
    return max_n

def solution(input_str):
    """
    Determine if the dissatisfaction can be exactly equal to k.

    Args:
        input_str: A string with two lines:
            First line: n and k
            Second line: sequence of 'Y', 'N', '?'

    Returns:
        "YES\n" if possible, "NO\n" otherwise
    """
    n, k = map(int, input_str.strip().split('\n')[0].split())
    sequence = list(input_str.strip().split('\n')[1])

    # Find positions of '?'
    q_positions = [i for i, c in enumerate(sequence) if c == '?']

    # Try all combinations of '?' assignments (brute force)
    can_achieve = False

    for assignment in itertools.product([False, True], repeat=len(q_positions)):
        current_sequence = list(sequence)
        for j, val in enumerate(assignment):
            current_sequence[q_positions[j]] = 'N' if val else 'Y'

        max_n = calculate_max_consecutive_n(current_sequence)
        if max_n == k:
            can_achieve = True
            break

    return "YES\n" if can_achieve else "NO\n"
