            return 1
        if col == n:
            return 0

        count = 0
        for v in range(1, n + 1):
            if used_mask & (1 << (v - 1)):
                continue
            if prev_row_vals and v == prev_row_vals[col]:
                continue
            new_used = used_mask | (1 << (v - 1))
            count = (count + count_from(row, col + 1, new_used, [v] + prev_row_vals[:col]))
        return count

    total = 0
    for i in range(n):
        row_used_mask = 0
        for j in range(n):
            actual = matrix[i][j]
            row_used_mask |= (1 << (actual - 1))
            for v in range(1, actual):
                if row_used_mask & (1 << (v - 1)):
                    continue
                if i > 0 and v == matrix[i - 1][j]:
                    continue
                row_used_mask_with_v = row_used_mask | (1 << (v - 1))
                total = (total + count_from(i, j + 1, row_used_mask_with_v, [v] + ([matrix[i - 1][k] for k in range(j+1)] if i > 0 else [])))

    return str(total % MOD)
