The problem asks us to find a shortest-path tree from a given vertex u that minimizes the total edge weight. We need to:

1. Find all shortest distances from vertex u using Dijkstra's algorithm
2. For each vertex (except u), select an incoming edge that maintains the shortest distance property (dist[parent] + weight == dist[current])
3. Among all valid choices, pick the one with minimum weight to minimize total tree weight

```python
#include <queue>
#include <vector>
#include <string>
#include <algorithm>
#include <sstream>
#include <cctype>

using namespace std;

string solution(string input_str) {
    stringstream ss(input_str);
    string line;

    if (!getline(ss, line)) return "";

    int n, m;
    ss >> n >> m;

    vector<tuple<int, int, int, int>> edges;
    edges.reserve(m);

    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        edges.emplace_back(u, v, w, i + 1);
    }

    int start = cin >> start;

    vector<pair<int, pair<int, int>>> adj[300005];
    for (auto& e : edges) {
        int u = get<0>(e);
        int v = get<1>(e);
        int w = get<2>(e);
        int idx = get<3>(e);
        adj[u].push_back({v, {w, idx}});
        adj[v].push_back({u, {w, idx}});
    }

    vector<long long> dist(n + 1, numeric_limits<long long>::max());
    dist[start] = 0;

    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    pq.push({0, start});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();

        if (d > dist[u]) continue;

        for (auto& edge : adj[u]) {
            int v = edge.first;
            int w = edge.second.first;

            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }

    vector<int> tree_edges;
    long long total_weight = 0;

    for (int v = 1; v <= n; v++) {
        if (v == start) continue;

        int best_idx = -1;
        long long best_w = numeric_limits<long long>::max();

        for (auto& edge : adj[v]) {
            int u = edge.first;
            int w = edge.second.first;
            int idx = edge.second.second;

            if (dist[u] + w == dist[v] && w < best_w) {
                best_w = w;
                best_idx = idx;
            }
        }

        if (best_idx != -1) {
            tree_edges.push_back(best_idx);
            total_weight += best_w;
        }
    }

    stringstream out;
    out << total_weight << "\n";
    out << *tree_edges;
    for (int i = 1; i < tree_edges.size(); i++) {
        out << " " << tree_edges[i];
    }

    return out.str();
}
