def real_solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        u, v, w = map(int, lines[1 + i].split())
        edges.append((u, v, w, i + 1))

    start = int(lines[m + 1])

    adj = [[] for _ in range(n + 1)]
    for u, v, w, idx in edges:
        adj[u].append((v, w, idx))
        adj[v].append((u, w, idx))

    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist[u]:
            continue

        for v, w, idx in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    tree_edges = []
    total_weight = 0

    for v in range(1, n + 1):
        if v == start:
            continue

        best_idx = -1
        best_w = float('inf')

        for u, w, idx in adj[v]:
            if dist[u] + w == dist[v]:
                if w < best_w:
                    best_w = w
                    best_idx = idx

        tree_edges.append(best_idx)
        total_weight += best_w

    return f"{total_weight}\n{' '.join(map(str, tree_edges))}"

