def solution(input_data):
    parts = input_data.strip().split()
    if len(parts) < 2:
        return "0\n"
    x = int(parts[0])
    y = int(parts[1])

    if y == 0:
        return "0\n"
    if x == 1:
        return str(y) + "\n"

    g = gcd(x, y)
    steps = 0
    curr = y
    while curr > 0:
        curr_gcd = gcd(x, curr)
        steps += curr // curr_gcd
        curr %= curr_gcd
    return str(steps) + "\n"
