import sys
from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    def parse_rows(lines, start):
        rows = []
        for i in range(n):
            rows.append(list(map(int, lines[start + i].split())))
        return rows

    A = parse_rows(lines, 1)
    B = parse_rows(lines, 1 + n)

    # Check if row multisets are identical
    A_rows = [tuple(r) for r in A]
    B_rows = [tuple(r) for r in B]
    if sorted(A_rows) != sorted(B_rows):
        return '-1'

    # Build target permutation
    matched = [-1] * n
    used_B = set()
    for i in range(n):
        for j in range(n):
            if A[i] != B[j]:
                continue
            matched[i] = j
            used_B.add(j)
            break

    # Greedy column selection
    result = []
    current = [list(row) for row in A]

    for step in range(5000):
        best_col = None
        best_moves = 0

        for col in range(1, m + 1):
            test = sorted(current, key=lambda r: r[col - 1])
            moves = sum(1 for i in range(n) if test[i] == B[matched[i]])
            if moves > best_moves:
                best_moves = moves
                best_col = col

        if best_col is not None:
            result.append(best_col)
            current.sort(key=lambda r: r[best_col - 1])
        else:
            break

    if current == B:
        return f"{len(result)}\n" + " ".join(map(str, result))
    else:
        return '-1'
