from collections import defaultdict
from itertools import combinations

def solve_match(a, b):
    """
    Find the best match score where Team A scores exactly 'a' points
    and opponent scores exactly 'b' points.
    Best means maximizing (A_wins - B_wins), so try 3-0 > 3-1 > 3-2
    """

    # Generate all valid set score pairs for each winner type
    A_wins_set = []  # (points_A, points_B) where A wins the set
    B_wins_set = []  # (points_A, points_B) where B wins the set

    # Regular sets (sets 1-4): 25+ with 2 point lead
    for pa in range(101):
        for pb in range(101):
            if pa >= 25 and pb <= 23 and pa - pb >= 2:
                A_wins_set.append((pa, pb))
            elif pb >= 25 and pa <= 23 and pb - pa >= 2:
                B_wins_set.append((pa, pb))

    # Deciding set (set 5 if reached): 15+ with 2 point lead
    for pa in range(161):
        for pb in range(161):
            if pa >= 15 and pb <= 13 and pa - pb >= 2:
                A_wins_set.append((pa, pb))
            elif pb >= 15 and pa <= 13 and pb - pa >= 2:
                B_wins_set.append((pa, pb))

    # Try 3-0 (A wins all 3 sets)
    for i in range(len(A_wins_set)):
        for j in range(i, len(A_wins_set)):
            for k in range(j, len(A_wins_set)):
                s1, s2, s3 = A_wins_set[i], A_wins_set[j], A_wins_set[k]
                sa = s1[0] + s2[0] + s3[0]
                sb = s1[1] + s2[1] + s3[1]
                if sa == a and sb == b:
                    score_str = f"3:0"
                    set_str = f"{s1[0]}:{s1[1]} {s2[0]}:{s2[1]} {s3[0]}:{s3[1]} "
                    return score_str + "\n" + set_str

    # Try 3-1 (A wins 3 sets, opponent wins 1)
    for i in range(4):
        for j in range(len(A_wins_set)):
            for k in range(j, len(A_wins_set)):
                for l in range(k, len(A_wins_set)):
                    s1, s2, s3, s4 = A_wins_set[j], A_wins_set[k], A_wins_set[l], B_wins_set[i]
                    sa = s1[0] + s2[0] + s3[0] + s4[0]
                    sb = s1[1] + s2[1] + s3[1] + s4[1]
                    if sa == a and sb == b:
                        score_str = f"3:1"
                        set_str = f"{s1[0]}:{s1[1]} {s2[0]}:{s2[1]} {s3[0]}:{s3[1]} {s4[0]}:{s4[1]} "
                        return score_str + "\n" + set_str

    # Try 3-2 (A wins 3 sets, opponent wins 2)
    for i in range(5):
        for j in range(len(A_wins_set)):
            for k in range(j, len(A_wins_set)):
                for l in range(k, len(A_wins_set)):
                    for m in range(5):
                        sa = 0
                        sb = 0
                        scores = []
                        for score in [A_wins_set[j], A_wins_set[k], A_wins_set[l], B_wins_set[m], B_wins_set[i]]:
                            sa += score[0]
                            sb += score[1]
                            scores.append(f"{score[0]}:{score[1]}")
                        if sa == a and sb == b:
                            score_str = "3:2"
                            set_str = " ".join(scores) + " "
                            return score_str + "\n" + set_str

    return "Impossible\n"

def solution(input_str):
    lines = input_str.strip().split('\n')
    m = int(lines[0])
